            { id: 'unlockDiplomacy', label: '解锁外交', completed: false, description: '条件：声望 ≥ 10 且刘表庇护 ≥ 60 后，外交 tab 将解锁。', nextHint: '解锁后可结盟、借道、示好或求援。' }
